perl_uid()
{
    if [ "$1" = -u ]; then
	/usr/bin/perl -e 'print "$>\n"'
    elif [ "$1" = -g ]; then
	/usr/bin/perl -e 'print $)=~/([^ ]+).*/,"\n"'
    fi
}

id=/usr/bin/id
# if /usr/xpg4/bin/id exists, it more likely to support -u
if [ -x /usr/xpg4/bin/id ]; then
    id=/usr/xpg4/bin/id
fi

# Check whether it supports -u
"$id" -u >/dev/null 2>&1
if [ $? -ne 0 ]; then
    id=perl_uid
fi
export id

